class Solution {
public:
    bool validSquare(vector<int>& p1, vector<int>& p2, vector<int>& p3, vector<int>& p4) {
        vector<vector<int>> pts = {p1, p2, p3, p4};
        long long d[6];
        int idx = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = i + 1; j < 4; j++) {
                long long dx = (long long)pts[i][0] - pts[j][0];
                long long dy = (long long)pts[i][1] - pts[j][1];
                d[idx++] = dx * dx + dy * dy;
            }
        }
        sort(d, d + 6);
        // sides: d[0..3] equal and > 0; diagonals: d[4..5] equal and = 2*side
        return d[0] > 0 && d[0] == d[1] && d[1] == d[2] && d[2] == d[3]
            && d[3] != d[4] && d[4] == d[5] && d[4] == 2 * d[0];
    }
};
